const message = ($json.message_text || '').toLowerCase();
const fullCatalog = $json.catalog_text;

// Split catalog into product blocks (separated by blank lines)
const blocks = fullCatalog.split('\n\n');

const hairKeywords = ['hair', 'mousse', 'pomade', 'spray', 'oil'];
const bodyKeywords = ['body', 'lotion', 'jelly', 'wash', 'perfume', 'mosquito', 'baby'];

let mentionsHair = hairKeywords.some(k => message.includes(k));
let mentionsBody = bodyKeywords.some(k => message.includes(k));

let filtered;
if (mentionsHair && !mentionsBody) {
  filtered = blocks.filter(b => b.includes('(Hair)'));
} else if (mentionsBody && !mentionsHair) {
  filtered = blocks.filter(b => b.includes('(Body)'));
} else {
  // unclear intent, or general question — send everything
  filtered = blocks;
}

return [{ json: { ...$json, catalog_text: filtered.join('\n\n') } }];

const reply = String($json.output || '').trim();

const marker = reply.match(/^\[\[CHECKOUT:(\{[\s\S]*\})\]\]$/);
let checkoutRequest = null;

if (marker) {
  try {
    const candidate = JSON.parse(marker[1]);
    if (Array.isArray(candidate.items) && candidate.items.length > 0) {
      checkoutRequest = candidate;
    }
  } catch (error) {
    checkoutRequest = null;
  }
}

const hasDollarSign = /\$/.test(reply);
const hasUSD = /\bUSD\b/i.test(reply);
const hasOtherCurrency = /\b(dollars?|euros?|EUR|GBP|pounds?)\b/i.test(reply);

return [{
  json: {
    ...$json,
    reply_message: checkoutRequest
      ? ''
      : (hasDollarSign || hasUSD || hasOtherCurrency)
        ? 'Let me confirm that exact pricing with our team and get right back to you! 🙏'
        : (reply || 'Sorry, I could not complete that request. Please try again shortly.'),
    checkout_request: checkoutRequest,
  },
}];

function levenshtein(a, b) {
  a = a.toLowerCase(); b = b.toLowerCase();
  const dp = [];
  for (let i = 0; i <= a.length; i++) dp.push([i]);
  for (let j = 0; j <= b.length; j++) dp[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      dp[i][j] = a[i-1] === b[j-1] ? dp[i-1][j-1] : 1 + Math.min(dp[i-1][j-1], dp[i-1][j], dp[i][j-1]);
    }
  }
  return dp[a.length][b.length];
}

const message = ($json.message_text || '').toLowerCase();
const catalog = $json.catalog_text || '';
const blocks = catalog.split('\n\n').filter(b => b.trim());

const products = blocks.map(b => {
  const firstLine = b.split('\n')[0];
  const name = firstLine.split('—')[0].trim();
  return { name, block: b };
});

const messageWords = message.replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length >= 3);

function scoreProduct(product) {
  const aliases = product.name.toLowerCase().split('/').map(s => s.trim()).filter(Boolean);
  let best = 0;
  for (const alias of aliases) {
    if (message.includes(alias)) { best = Math.max(best, 0.95); continue; }
    const aliasWords = alias.split(/\s+/).filter(w => w.length >= 3);
    for (const mw of messageWords) {
      for (const aw of aliasWords) {
        const dist = levenshtein(mw, aw);
        const sim = 1 - dist / Math.max(mw.length, aw.length);
        if (sim > best) best = sim;
      }
    }
  }
  return best;
}

const scored = products
  .map(p => ({ ...p, score: scoreProduct(p) }))
  .filter(p => p.score >= 0.72)
  .sort((a, b) => b.score - a.score);

let matchNote = '';
if (scored.length === 1) {
  matchNote = `\n\nMATCHED PRODUCT FOR THIS MESSAGE — this is the specific product the customer is asking about. Use this exact data (name, price, wholesale price, min qty) when answering. Do not use any other product's numbers:\n${scored[0].block}\n`;
} else if (scored.length > 1) {
  const uniqueNames = [...new Set(scored.map(p => p.name))];
  if (uniqueNames.length > 1) {
    matchNote = `\n\nPOSSIBLE MATCHES FOR THIS MESSAGE — these are genuinely different products. If the customer hasn't already specified which one, ask them to clarify before quoting a price:\n${scored.map(p => p.block).join('\n\n')}\n`;
  } else {
    matchNote = `\n\nMATCHED PRODUCT FOR THIS MESSAGE — this is the specific product the customer is asking about. Use this exact data when answering:\n${scored[0].block}\n`;
  }
}

return [{ json: { ...$json, catalog_text: catalog + matchNote } }];

// -------------------------------------------
// CUSTOMER MESSAGE
// -------------------------------------------

const message = (
  (
    $('Extract Fields').isExecuted
      ? $('Extract Fields').item.json.message_text
      : $('Edit Fields').item.json.message_text
  ) || ''
).toLowerCase().trim();


// -------------------------------------------
// GET STRUCTURED PRODUCT CATALOG
// -------------------------------------------

let products = $json.products || [];

if (typeof products === 'string') {
  try {
    products = JSON.parse(products);
  } catch (error) {
    products = [];
  }
}

if (!Array.isArray(products)) {
  products = [];
}


// -------------------------------------------
// NORMALIZATION
// -------------------------------------------

function normalize(text = '') {
  return String(text)
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const normalizedMessage = normalize(message);

const messageWords = normalizedMessage
  .split(' ')
  .filter(word => word.length >= 2);


// -------------------------------------------
// DETECT CATEGORY / LIST REQUESTS FIRST
// -------------------------------------------

const listPatterns = [
  /\ball\b/, /\blist\b/, /\bshow\b/, /\bproducts\b/, /\bavailable\b/,
  /\bwhat do you have\b/, /\bwhat products\b/, /\bwhich products\b/
];

const wantsList = listPatterns.some(pattern => pattern.test(normalizedMessage));
const wantsHairCategory = /\bhair\b/.test(normalizedMessage);
const wantsBodyCategory = /\bbody\b/.test(normalizedMessage);

const requestedProductCategory =
  wantsHairCategory && !wantsBodyCategory ? 'hair' :
  wantsBodyCategory && !wantsHairCategory ? 'body' : null;

// Category terms constrain a product search; they create a list only if list intent exists.
const forceCategory = wantsList ? requestedProductCategory : null;
const wantsFullCatalog = wantsList || /^(all|everything|both)$/i.test(normalizedMessage);

// A buyer-type follow-up (e.g. "wholesale would be better") needs the
// live catalog so prices are never recovered from conversation memory.
const isPricingFollowUp =
  /\b(wholesale|retail|bulk|personal use)\b/.test(normalizedMessage);

// Quantity-only messages often follow a product and buyer-type selection,
// e.g. “25 of each”. They must receive live prices, never memory-only data.
const isQuantityFollowUp =
  /\b\d+\s*(?:of\s+each|each|units?|unit|pieces?|piece|pcs?)\b/.test(normalizedMessage) ||
  /^\d+$/.test(normalizedMessage);

// A short affirmative can be a confirmation of the checkout link offered in
// the immediately preceding assistant message. Keep the live catalog available
// so the agent can validate the remembered selection against it.
const isCheckoutConfirmation =
  /^(?:yes|yeah|yep|yup|sure|okay|ok|go ahead|proceed|please do|do it|send it|send the link|continue)$/i
    .test(normalizedMessage);

// -------------------------------------------
// LEVENSHTEIN
// -------------------------------------------

function levenshtein(a, b) {
  a = normalize(a);
  b = normalize(b);

  const matrix = [];

  for (let i = 0; i <= b.length; i++) {
    matrix[i] = [i];
  }

  for (let j = 0; j <= a.length; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {

      if (b[i - 1] === a[j - 1]) {
        matrix[i][j] =
          matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }

  return matrix[b.length][a.length];
}


function similarity(a, b) {
  a = normalize(a);
  b = normalize(b);

  if (!a || !b) return 0;

  const distance = levenshtein(a, b);

  return 1 - (
    distance /
    Math.max(a.length, b.length)
  );
}


// -------------------------------------------
// GENERIC WORDS
// -------------------------------------------

const genericWords = new Set([
  'hair',
  'body',
  'baby',
  'oil',
  'cream',
  'spray',
  'wash',
  'white',
  'blue',
  'green',
  'pink'
]);


// -------------------------------------------
// DETECT SIZE
// -------------------------------------------

function extractSize(text) {
  const compact = String(text)
    .toLowerCase()
    .replace(/\s+/g, '');

  const match = compact.match(
    /(\d+(?:\.\d+)?)(ml|g|kg|l|litre|liter|oz)\b/i
  );

  return match
    ? normalize(match[0]).replace(/\s/g, '')
    : null;
}

const requestedSize = extractSize(message);


// -------------------------------------------
// DETECT COLOR
// -------------------------------------------

const knownColors = [
  'white',
  'black',
  'blue',
  'green',
  'pink',
  'yellow',
  'purple',
  'gold',
  'light'
];

const requestedColors = knownColors.filter(
  color => messageWords.includes(color)
);


// -------------------------------------------
// PRODUCT SCORING
// -------------------------------------------

function scoreProduct(product) {

  const name = normalize(product.name);
  const category = normalize(product.category);

  let score = 0;

  const productWords = name
    .split(' ')
    .filter(word => word.length >= 2);


  // Exact full product name
  if (
    name &&
    normalizedMessage.includes(name)
  ) {
    score += 120;
  }


  // Individual product-name words
  for (const productWord of productWords) {

    const isGeneric =
      genericWords.has(productWord);

    if (messageWords.includes(productWord)) {
      score += isGeneric ? 6 : 25;
      continue;
    }

    for (const messageWord of messageWords) {

      const sim = similarity(
        productWord,
        messageWord
      );

      if (sim >= 0.84) {
        score += isGeneric ? 3 : 15;
        break;
      }
    }
  }


  // Category contributes only a small score
  if (
    category &&
    messageWords.includes(category)
  ) {
    score += 4;
  }


  // Variant details
  for (const variant of product.variants || []) {

    if (
      variant.size &&
      requestedSize &&
      normalize(variant.size).replace(/\s/g, '') === requestedSize
    ) {
      score += 35;
    }

    for (const color of variant.colors || []) {

      if (
        requestedColors.includes(
          normalize(color)
        )
      ) {
        score += 4;
      }
    }
  }

  return score;
}


// -------------------------------------------
// SCORE ALL PRODUCTS
// -------------------------------------------

const productCandidates = requestedProductCategory
  ? products.filter(product => normalize(product.category) === requestedProductCategory)
  : products;

const scoredProducts = productCandidates
  .map(product => ({
    ...product,
    _score: scoreProduct(product)
  }))
  .filter(product => product._score > 0)
  .sort((a, b) => b._score - a._score);


// -------------------------------------------
// CHOOSE RELEVANT PRODUCTS
// -------------------------------------------

let relevantProducts = [];
let catalogMode = 'no_match';


// CATEGORY LIST REQUEST HAS TOP PRIORITY

if (wantsFullCatalog || isPricingFollowUp || isQuantityFollowUp || isCheckoutConfirmation) {
  catalogMode = isCheckoutConfirmation
    ? 'checkout_confirmation'
    : (isPricingFollowUp || isQuantityFollowUp) && !wantsFullCatalog
      ? 'pricing_follow_up'
      : 'category_list';
  relevantProducts = forceCategory
    ? products.filter(product => normalize(product.category) === forceCategory)
    : products;
} else if (scoredProducts.length > 0) {
  const bestScore = scoredProducts[0]._score;
  catalogMode = requestedSize ? 'variant_match' : 'product_match';
  const hasMultipleRequests = /\band\b|,/.test(normalizedMessage);

  // Retain one plausible match per requested product.
  if (hasMultipleRequests) {
    relevantProducts = scoredProducts
      .filter(product => product._score >= 20)
      .slice(0, 5);
  } else if (bestScore >= 60) {
    relevantProducts = scoredProducts
      .filter(product => product._score >= bestScore * 0.55)
      .slice(0, 5);
  } else {
    relevantProducts = scoredProducts
      .filter(product => product._score >= bestScore * 0.75)
      .slice(0, 5);
  }
}


// -------------------------------------------
// CATEGORY FALLBACK
// -------------------------------------------

if (
  relevantProducts.length === 0 &&
  !forceCategory
) {

  const hairWords = [
    'hair',
    'mousse',
    'pomade',
    'spray',
    'styling',
    'shampoo'
  ];

  const bodyWords = [
    'body',
    'lotion',
    'jelly',
    'wash',
    'perfume',
    'mosquito',
    'cream'
  ];

  const mentionsHair = hairWords.some(
    word =>
      normalizedMessage.includes(word)
  );

  const mentionsBody = bodyWords.some(
    word =>
      normalizedMessage.includes(word)
  );


  if (mentionsHair && !mentionsBody) {

    catalogMode = 'category_browse';

    relevantProducts = products
      .filter(
        product =>
          normalize(product.category) ===
          'hair'
      )
      .slice(0, 8);

  } else if (
    mentionsBody &&
    !mentionsHair
  ) {

    catalogMode = 'category_browse';

    relevantProducts = products
      .filter(
        product =>
          normalize(product.category) ===
          'body'
      )
      .slice(0, 8);
  }
}


// -------------------------------------------
// FILTER VARIANTS
// Do NOT reduce variants for full category lists
// -------------------------------------------

if (catalogMode !== 'category_list') {

  relevantProducts =
    relevantProducts.map(product => {

      const variants =
        product.variants || [];

      let matchedVariants = variants;


      // SIZE FILTER

      if (requestedSize) {

        const sizeMatches =
          variants.filter(variant => {

            if (!variant.size) {
              return false;
            }

            const variantSize =
              normalize(
                variant.size
              ).replace(/\s/g, '');

            return (
              variantSize ===
              requestedSize
            );
          });

        if (sizeMatches.length > 0) {
          matchedVariants =
            sizeMatches;
        }
      }


      // COLOR FILTER

      if (
        requestedColors.length > 0
      ) {

        const colorMatches =
          matchedVariants.filter(
            variant =>
              (variant.colors || [])
                .some(color =>
                  requestedColors.includes(
                    normalize(color)
                  )
                )
          );

        if (colorMatches.length > 0) {
          matchedVariants =
            colorMatches;
        }
      }


      return {
        ...product,
        variants: matchedVariants
      };
    });
}


// -------------------------------------------
// FINAL MODE CHECK
// -------------------------------------------

if (relevantProducts.length === 0) {
  catalogMode = 'no_match';
}


// -------------------------------------------
// SIZE CLARIFICATION CHECK
// -------------------------------------------

if (
  catalogMode === 'product_match' &&
  relevantProducts.length === 1 &&
  !requestedSize
) {

  const onlyProduct = relevantProducts[0];

  const distinctSizes = [
    ...new Set(
      (onlyProduct.variants || [])
        .map(v => v.size)
        .filter(Boolean)
    )
  ];

  if (distinctSizes.length > 1) {
    catalogMode = 'needs_size_clarification';
  }
}


// -------------------------------------------
// FORMAT PRODUCT FOR AI
// -------------------------------------------

function formatProduct(product) {

  let text = `${product.name}`;

  text +=
    `\nCategory: ${product.category}`;


  const colors = [
    ...new Set(
      (product.variants || [])
        .flatMap(
          variant =>
            variant.colors || []
        )
    )
  ];

  if (colors.length > 0) {
    text +=
      `\nColors: ${colors.join(', ')}`;
  }


  text += `\nVariants:`;


  for (
    const variant of
    product.variants || []
  ) {

    text += '\n';

    if (variant.size) {
      text += `${variant.size}: `;
    }

    if (
      variant.retail_price_ugx !== null &&
      variant.retail_price_ugx !== undefined
    ) {

      text +=
        `${variant.retail_price_ugx} UGX`;

    } else {

      text += `Price on request`;
    }


    text +=
      ` | Stock: ${
        variant.stock_status ||
        'Unknown'
      }`;


    if (
      variant.wholesale_price_ugx !== null &&
      variant.wholesale_price_ugx !== undefined &&
      variant.wholesale_min_qty !== null &&
      variant.wholesale_min_qty !== undefined
    ) {

      text +=
        ` | Wholesale: ${variant.wholesale_price_ugx} UGX`;

      text +=
        ` | Minimum: ${variant.wholesale_min_qty}`;
    }
  }

  return text;
}


// -------------------------------------------
// BUILD AI CONTEXT
// -------------------------------------------

let catalogText = '';

if (catalogMode === 'needs_size_clarification') {

  const onlyProduct = relevantProducts[0];

  const availableSizes = [
    ...new Set(
      (onlyProduct.variants || [])
        .map(v => v.size)
        .filter(Boolean)
    )
  ];

  catalogText = `${onlyProduct.name}\nCategory: ${onlyProduct.category}\nAvailable sizes: ${availableSizes.join(', ')}\n\nDo NOT state any price yet. Ask the customer which size they want first, listing only the sizes above (no prices). Once they specify a size, the correct price for that size will be supplied.`;

} else if (catalogMode === 'checkout_confirmation') {

  catalogText = relevantProducts.map(product => product.name).join('\n');
} else if (relevantProducts.length > 0) {

  catalogText =
    relevantProducts
      .map(formatProduct)
      .join('\n\n');

} else {

  catalogText = `
NO DIRECT PRODUCT MATCH FOUND.

No reliable product from the current catalog was selected for this message.

Conversation history may be used only to understand what the customer is referring to.

Do not use conversation history as a source of product names, prices, sizes, colors, stock, or other product facts.

If the intended product is still unclear, ask the customer to clarify.

Do not invent product information.
`.trim();
}


// -------------------------------------------
// REMOVE INTERNAL SCORES
// -------------------------------------------

const cleanProducts =
  relevantProducts.map(product => {

    const {
      _score,
      ...cleanProduct
    } = product;

    return cleanProduct;
  });


// -------------------------------------------
// OUTPUT
// -------------------------------------------

return [
  {
    json: {
      ...$json,

      customer_message:
        message,

      catalog_mode:
        catalogMode,

      requested_category:
        forceCategory,

      requested_size:
        requestedSize,

      requested_colors:
        requestedColors,

      matched_products:
        cleanProducts,

      match_count:
        cleanProducts.length,

      catalog_text:
        catalogText
    }
  }
];

const raw = $json.catalog_text || '';
const blocks = raw.split('\n\n').map(b => b.trim()).filter(Boolean);

const products = [];

for (const block of blocks) {
  const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
  if (lines.length === 0) continue;

  const name = lines[0];
  let category = '';
  let colors = [];
  const variants = [];

  for (const line of lines.slice(1)) {
    if (line.startsWith('Category:')) {
      category = line.replace('Category:', '').trim();
    } else if (line.startsWith('Colors:')) {
      colors = line.replace('Colors:', '').split(',').map(c => c.trim()).filter(Boolean);
    } else if (line.startsWith('Variants:')) {
      // marker line, skip
    } else if (line.startsWith('•')) {
      const variantLine = line.replace(/^•\s*/, '');
      const match = variantLine.match(/^(?:(.+?)\s*—\s*)?UGX\s*([\d,]+)\s*—\s*([^|]+?)(?:\s*\|\s*Wholesale:\s*UGX\s*([\d,]+)\s*each from\s*([\d,]+)\s*units)?$/i);
      if (match) {
        const size = match[1] ? match[1].trim() : null;
        const retail_price_ugx = parseInt(match[2].replace(/,/g, ''), 10);
        const stock_status = match[3].trim();
        const wholesale_price_ugx = match[4] ? parseInt(match[4].replace(/,/g, ''), 10) : null;
        const wholesale_min_qty = match[5] ? parseInt(match[5].replace(/,/g, ''), 10) : null;
        variants.push({ size, colors, retail_price_ugx, stock_status, wholesale_price_ugx, wholesale_min_qty });
      }
    }
  }

  if (variants.length > 0) {
    products.push({ name, category, variants });
  }
}

return [{ json: { ...$json, products } }];

const checkoutUrl = $json.checkout_url || $json.body?.checkout_url || $json.data?.checkout_url;
const checkoutRequest = $('Sign Checkout Request').item.json.checkout_request || {};
const requestedItems = Array.isArray(checkoutRequest.items) ? checkoutRequest.items : [];
const itemNames = requestedItems.map((item) => item.product_name || 'that product').filter(Boolean);
const responseMessage = String($json.message || $json.body?.message || $json.errors?.items?.[0] || $json.body?.errors?.items?.[0] || $json.error?.description || $json.error?.message || $json.errorDescription || '').trim();
const stockProblem = /no longer has enough stock|out of stock|unavailable/i.test(responseMessage);
const productLabel = itemNames.length === 1 ? itemNames[0] : 'one or more selected products';
const replyMessage = checkoutUrl
  ? `Great — here is your secure checkout link: ${checkoutUrl}

Please complete your delivery and payment details on the website. Your order is not placed until checkout is completed.`
  : stockProblem
    ? `Sorry, ${productLabel} is currently out of stock or does not have enough units for this order.

You can try another product, or send a smaller quantity and I’ll check availability for you.`
    : 'Sorry, I could not create the checkout link just now. Please try again shortly or ask our team to assist.';
return [{json:{...$json,reply_message:replyMessage}}];

function utf8Bytes(value) {
  const encoded = encodeURIComponent(String(value));
  const bytes = [];
  for (let index = 0; index < encoded.length; index += 1) {
    if (encoded[index] === '%') {
      bytes.push(parseInt(encoded.slice(index + 1, index + 3), 16));
      index += 2;
    } else {
      bytes.push(encoded.charCodeAt(index));
    }
  }
  return bytes;
}
function rightRotate(value, amount) {
  return (value >>> amount) | (value << (32 - amount));
}
function sha256(input) {
  const bytes = Array.from(input);
