const history=$('Load campaign history').all().map(x=>x.json);
const prospects=new Map($input.all().map(x=>[x.json.id,x.json]));
const key=r=>(r.outreach_cycle||'legacy')+'|'+normalizePhone(r.phone_number);
const blocked=new Set(history.filter(r=>['sent','sent_duplicate','followed_up','replied','sending','skipped_duplicate'].includes(r.queue_status)).map(key));
